fn largest_divisor(n: i8) -> i8 {
    debug_assert!(n > 1, "Input must be strictly greater than 1");

    // Iterate downward from n-1 to 1 and return the first divisor we find.
    for d in (1..n).rev() {
        if n % d == 0 {
            return d;
        }
    }

    // For n > 1, we will always find at least 1 as a divisor.
    1
}

